{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    if "threshold" not in case or "calls" not in case:
        raise ValueError("case requires threshold and calls")

    threshold = case["threshold"]
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    if not math.isfinite(threshold) or threshold < 0:
        raise ValueError("threshold must be finite and nonnegative")

    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )
    diagnostics = []

    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("each call must be an object")
        if any(field not in call for field in required):
            raise ValueError("call is missing a required field")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        if isinstance(loss_without, bool) or not isinstance(loss_without, (int, float)):
            raise ValueError("loss_without_call must be a number")
        if isinstance(loss_with, bool) or not isinstance(loss_with, (int, float)):
            raise ValueError("loss_with_call must be a number")
        if not math.isfinite(loss_without) or not math.isfinite(loss_with):
            raise ValueError("losses must be finite")
        if loss_without < 0 or loss_with < 0:
            raise ValueError("losses must be nonnegative")
        if isinstance(prediction_tokens, bool) or not isinstance(prediction_tokens, int):
            raise ValueError("prediction_tokens must be an integer")
        if prediction_tokens < 0:
            raise ValueError("prediction_tokens must be nonnegative")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")

        normalized_gain = (loss_without - loss_with) / max(prediction_tokens, 1)
        accepted = parseable and normalized_gain >= threshold
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": round(normalized_gain, 6),
        })

    accepted_call_ids = [
        diagnostic["call_id"]
        for diagnostic in diagnostics
        if diagnostic["accepted"]
    ]
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
"}
